0fbd8bb0e9cfa04de4ee608bd6d139098aadabb429b111b\",\"event\":\"mr-kms\",\"event_payload\":\"0e67f00f3048e5320b7e16dba93a8370b7a1c3aba3626dae55dc5664c966c589\"},{\"imr\":3,\"event_type\":134217729,\"digest\":\"8c47135e47062ea02e06c936b41794fd438d5f45cf0d9c1da9bf57f6c6013e016b61785acbedff0f6e6852f242b26a6b\",\"event\":\"mr-kms\",\"event_payload\":\"de46a8d7a3b3660b01a77c5d2829c31ceedae0419b7bb2716c47c9224e0f4c1e\"},{\"imr\":3,\"event_type\":134217729,\"digest\":\"c936f709860155a455c519b505fe29bde21d1b778534a8f0b41b706b0f789eae2ea899e224fedb2331c18324aab4db93\",\"event\":\"os-image-hash\",\"event_payload\":\"bd369a8c2f9edb2b52dad48ac8e0b32dde5f1337c423a506b48d07403a7d8033\"},{\"imr\":3,\"event_type\":134217729,\"digest\":\"83368b43a0fc6f824f5a9220592df85fd30e2d405ecbd253a5c6354af63e6c9b41aec557c38a38e348ab87f9ac8fc68c\",\"event\":\"key-provider\",\"event_payload\":\"\"},{\"imr\":3,\"event_type\":134217729,\"digest\":\"ba51104636900268b0e059fa3d266419d079d1e94aea26fb9fcbb8d764bf4c89a67ac271b8a0d1a3989945132a111fc7\",\"event\":\"storage-fs\",\"event_payload\":\"7a6673\"},{\"imr\":3,\"event_type\":134217729,\"digest\":\"1a76b2a80a0be71eae59f80945d876351a7a3fb8e9fd1ff1cede5734aa84ea11fd72b4edfbb6f04e5a85edd114c751bd\",\"event\":\"system-ready\",\"event_payload\":\"\"}]","vm_config":"{\"os_image_hash\":\"bd369a8c2f9edb2b52dad48ac8e0b32dde5f1337c423a506b48d07403a7d8033\",\"cpu_count\":32,\"memory_size\":34359738368,\"qemu_version\":\"8.2.2\",\"pci_hole64_size\":0,\"hugepages\":false,\"num_gpus\":0,\"num_nvswitches\":0,\"hotplug_off\":false,\"image\":\"dstack-0.5.9-bd369a8c\",\"host_share_mode\":\"9p\",\"spec_version\":1}","app_compose":"{\"allowed_envs\":[\"PRIVATE_AI_GATEWAY_ADMIN_TOKEN\",\"PRIVATE_AI_GATEWAY_CONTROL_URL\",\"PRIVATE_AI_GATEWAY_CONTROL_TOKEN\",\"DSTACK_ROOT_PUBLIC_KEY\",\"CLOUDFLARE_API_TOKEN\",\"CERTBOT_EMAIL\",\"NODE_EXPORTER_USER\",\"NODE_EXPORTER_PASSWORD_HASH\",\"PRIVATE_AI_GATEWAY_PULL_TOKEN\",\"PRIVATE_AI_GATEWAY_PREFIX_HASH_SECRET\"],\"docker_compose_file\":\"# dstack / Phala deployment manifest for the private-ai-gateway stack via the launcher.\\n#\\n# The launcher image is the measured trust-root: pin it by @sha256 digest (the\\n# digest + this file are hashed into the TDX quote). The launcher clones+builds\\n# the gateway from source at boot; the attestation verifier is\\n# the gateway's vendored confidential_verifier package, so it needs no separate pin.\\n#\\n# The gateway's source pin + static config are inlined as compose `configs:`\\n# (measured into the attestation): the launcher clones the pin and the gateway\\n# reads the config from mounted files. Secret values are supplied as dstack\\n# ENCRYPTED SECRETS and referenced as ${VAR} so dstack injects them — only the\\n# variable names appear in this public file, never the values.\\n\\nservices:\\n  # TLS-terminating ingress: requests CAA-pinned Let's Encrypt certs via Cloudflare\\n  # DNS-01, registers under the dstack gateway domain, and reverse-proxies inbound\\n  # 443 to the launcher's gateway on :8086. Pin by @sha256 digest like the launcher.\\n  dstack-ingress:\\n    image: dstacktee/dstack-ingress:2.5@sha256:97285855a83ce6682447eb1f36e59c1927b9188a51b213e34d79acadd8425c78\\n    restart: unless-stopped\\n    # The ingress is an L4 TCP proxy: every client connection maps 1:1 to a\\n    # backend connection to the gateway, so it holds 2 fds per live connection.\\n    # haproxy has no `ulimit-n` in its config; it derives an fd need from MAXCONN\\n    # and raises its OWN soft nofile from the container hard limit. Pin the hard\\n    # limit here (like `launcher`) so MAXCONN is never silently capped by whatever\\n    # the docker daemon default happens to be. 65536 comfortably covers\\n    # MAXCONN 16384 (~33k fds) with headroom.\\n    ulimits:\\n      nofile:\\n        soft: 65536\\n        hard: 65536\\n    ports:\\n      - \\\"443:443\\\"\\n    environment:\\n      # --- public config: literals, measured into the attestation ---\\n      DNS_PROVIDER: cloudflare\\n      GATEWAY_DOMAIN: gateway.${DSTACK_GATEWAY_DOMAIN}\\n      SET_CAA: \\\"true\\\"\\n      # Concurrent-connection ceiling. The image default is 4096; under real\\n      # streaming load the ingress sat pinned at that ceiling ~84% of the time\\n      # (avg ~3720 concurrent), so once a burst pushed past 4096 haproxy stopped\\n      # accepting and clients saw a hang. Streaming LLM traffic keeps thousands of\\n      # long-lived connections open at once, so give a 4x headroom. Must stay well\\n      # under the nofile hard limit above (2 fds/conn in TCP mode).\\n      MAXCONN: \\\"16384\\\"\\n      # Idle (no-data) timeout, reset on any byte in either direction. The image\\n      # default is 86400s (24h): a client that stops reading, or an upstream that\\n      # goes silent, keeps its slot for a full day, which is how slots leaked\\n      # toward the ceiling. 1800s reaps a genuinely idle/stalled connection while\\n      # never touching a stream that is still flowing (even a slow one). NOTE:\\n      # this is the one value to confirm against the longest legitimate silent\\n      # gap a request can have — e.g. a reasoning model that thinks >30 min before\\n      # its first token would be cut. Raise if such requests are expected.\\n      TIMEOUT_CLIENT: 1800s\\n      TIMEOUT_SERVER: 1800s\\n      # Multi-domain TLS. The ingress is an L4 (TCP) proxy: it terminates TLS for\\n      # each hostname and forwards the DECRYPTED stream untouched, so the client's\\n      # original HTTP Host survives. The gateway uses that Host to pick the\\n      # matching downstream_tls_binding. All public hostnames route by SNI to the\\n      # same gateway listener (compose service name, not localhost). tee.redpill.ai\\n      # and inference.phala.com are the TEE-only domains (see `tee_only_domains`\\n      # below).\\n      DOMAINS: |\\n        tee.redpill.ai\\n        inference.phala.com\\n        api.redpill.ai\\n      ROUTING_MAP: |\\n        tee.redpill.ai=launcher:8086\\n        inference.phala.com=launcher:8086\\n        api.redpill.ai=launcher:8086\\n      # --- secrets: values come from dstack Encrypted Secrets (never commit values) ---\\n      # NOTE: this single Cloudflare token must have DNS-edit (and CAA) rights on\\n      # BOTH the redpill.ai and phala.com zones, or cert issuance for one fails.\\n      CLOUDFLARE_API_TOKEN: ${CLOUDFLARE_API_TOKEN}\\n      CERTBOT_EMAIL: ${CERTBOT_EMAIL}\\n    volumes:\\n      - /var/run/dstack.sock:/var/run/dstack.sock\\n      - /var/run/tappd.sock:/var/run/tappd.sock\\n      - cert-data:/etc/letsencrypt\\n      # Per-domain leaf certs (cert-<domain>.pem) the gateway reads to bind SPKI.\\n      - evidences:/evidences\\n\\n  launcher:\\n    image: ghcr.io/redpill-ai/private-ai-launcher@sha256:c083ff9e6a5ddf10f6c9e9bb1f74cc618deebecfea5208b563c574399db4637c\\n    restart: always\\n    # The gateway opens many fds (inbound conns, per-upstream pools, control-plane\\n    # + verifier calls). Docker's default nofile (often 1024) is far too low: under\\n    # load it hit EMFILE (\\\"Too many open files\\\"), which killed the gateway's accept\\n    # loop. Raise the limit well above peak concurrency.\\n    ulimits:\\n      nofile:\\n        soft: 65536\\n        hard: 65536\\n    # supervisord streams the gateway logs to the container stdout; cap the\\n    # runtime log on disk so it can't grow unbounded (~500MB total, rotated).\\n    # The gateway writes no per-request lines — startup, verification, and its\\n    # own errors only — so the volume is low.\\n    logging:\\n      driver: json-file\\n      options:\\n        max-size: \\\"100m\\\"\\n        max-file: \\\"5\\\"\\n    # no host port: traffic enters via dstack-ingress (443) and reaches the\\n    # gateway over the compose network as http://launcher:8086.\\n    expose:\\n      - \\\"8086\\\"\\n    volumes:\\n      - /var/run/dstack.sock:/var/run/dstack.sock   # only the gateway uses this\\n      - pal-cache:/var/lib/pag/cache                 # cargo/uv build cache (speeds reboots)\\n      - pal-state:/var/lib/pag/state                 # mutable upstreams.json + sessions.jsonl\\n      - evidences:/evidences:ro                      # ingress-minted per-domain leaf certs (cert-<domain>.pem)\\n    # Static gateway config + upstream seed are mounted from the `configs:` block\\n    # at the bottom (measured into the attestation). The source pin is passed via\\n    # `environment:` instead (see below).\\n    # `docker compose up` does NOT recreate the container when only a `configs:`\\n    # content changes, so the old file stays mounted. Bump this label whenever\\n    # gateway-config / gateway-upstreams change to force a recreate.\\n    labels:\\n      private-ai-gateway.config-rev: \\\"3\\\"\\n    configs:\\n      - source: gateway-config\\n        target: /etc/private-ai-gateway/gateway.config.json\\n      - source: gateway-upstreams\\n        target: /etc/private-ai-gateway/upstreams.seed.json\\n    environment:\\n      # The gateway reads its whole policy from this mounted static config file\\n      # (see `configs:` above); CONFIG_PATH is the only gateway-facing env var.\\n      - PRIVATE_AI_GATEWAY_CONFIG_PATH=/etc/private-ai-gateway/gateway.config.json\\n      # Tracing filter. The gateway does not log requests; failures are\\n      # accounted for in the control plane's usage pipeline.\\n      - RUST_LOG=info\\n      # Gateway source pin. These literals are measured into the attestation, and\\n      # because they live in `environment:` (part of Compose's config-hash) a\\n      # COMMIT_SHA bump forces a container recreate on `phala deploy` — so the new\\n      # pin actually takes effect. (A `configs:`-file pin would not: Compose ignores\\n      # config content when deciding to recreate, so the change would never apply.)\\n      # entrypoint.sh writes /etc/git-launcher/gateway.conf from these, and the\\n      # gateway reads that file as its attested source provenance.\\n      - PRIVATE_AI_GATEWAY_REPO_URL=https://github.com/Dstack-TEE/private-ai-gateway.git\\n      - PRIVATE_AI_GATEWAY_REPO_COMMIT=24a31ff1b33cb45cd2ad0ddac02749eb4ea424e2\\n      # NEAR AI verification posts TDX quotes to the dstack-verifier sidecar below;\\n      # reach it by compose service name (localhost would be the launcher itself).\\n      - DSTACK_VERIFIER_URL=http://dstack-verifier:8080\\n      # --- secrets: values come from dstack Encrypted Secrets (never commit values) ---\\n      # Control-plane credentials. The gateway's in-process middleware reads these\\n      # from the `middleware` config section below (rendered from the same secrets).\\n      - PRIVATE_AI_GATEWAY_CONTROL_URL=${PRIVATE_AI_GATEWAY_CONTROL_URL}\\n      - PRIVATE_AI_GATEWAY_CONTROL_TOKEN=${PRIVATE_AI_GATEWAY_CONTROL_TOKEN}\\n\\n  # TDX quote verifier for the NEAR AI path (reproduces ACPI/boot measurements via\\n  # QEMU). The gateway reaches it at http://dstack-verifier:8080 (DSTACK_VERIFIER_URL).\\n  dstack-verifier:\\n    image: ghcr.io/dstack-tee/dstack-verifier:0.6.0-rc5@sha256:3710ec5c408a0d04e408668905152cc8c972396c0fa3d942158c5e67e969628d\\n    restart: unless-stopped\\n    logging:\\n      driver: json-file\\n      options:\\n        max-size: \\\"50m\\\"\\n        max-file: \\\"5\\\"\\n\\n  # Host-metrics exporter for observing this CVM (CPU/mem/disk/net/fd). Inside a\\n  # CVM the container's /, /proc, /sys ARE the guest's, so node-exporter reports\\n  # the CVM's own state. Pinned by @sha256 like the other images (measured into\\n  # the attestation). Exposed on 9100 (reached via the dstack gateway) and guarded\\n  # by HTTP basic auth — both username and the bcrypt password HASH are injected as\\n  # dstack Encrypted Secrets, so neither appears in this measured file.\\n  node-exporter:\\n    image: prom/node-exporter:v1.8.2@sha256:4032c6d5bfd752342c3e631c2f1de93ba6b86c41db6b167b9a35372c139e7706\\n    restart: unless-stopped\\n    pid: host\\n    command:\\n      - '--path.rootfs=/host'\\n      - '--path.procfs=/host/proc'\\n      - '--path.sysfs=/host/sys'\\n      - '--web.config.file=/etc/node-exporter/web-config.yml'\\n    volumes:\\n      - /:/host:ro,rslave\\n    configs:\\n      - source: node-exporter-web-config\\n        target: /etc/node-exporter/web-config.yml\\n    ports:\\n      - \\\"9100:9100\\\"\\n    logging:\\n      driver: json-file\\n      options:\\n        max-size: \\\"10m\\\"\\n        max-file: \\\"3\\\"\\n\\nvolumes:\\n  pal-cache:\\n  pal-state:\\n  cert-data:   # Let's Encrypt certs/keys persisted for dstack-ingress\\n  evidences:   # ingress attestation evidence + per-domain leaf certs, shared read-only with the gateway\\n\\n# Inlined, measured into the attestation. Public pins use LITERAL values so the\\n# code version is bound into compose_hash; only secrets use ${VAR} (injected by\\n# dstack, never measured).\\nconfigs:\\n  # Static gateway config. `admin_token`, the dedicated upstream pull token, and\\n  # the control-plane credentials are secrets — ${VAR} keeps their values out of\\n  # the measured compose while the presence and destination stay measured. The\\n  # `middleware` section runs the in-process middleware, which consults the control\\n  # plane at `control_url`.\\n  gateway-config:\\n    content: |\\n      {\\n        \\\"bind\\\": \\\"0.0.0.0:8086\\\",\\n        \\\"state_dir\\\": \\\"/var/lib/pag/state\\\",\\n        \\\"upstream_config_seed_path\\\": \\\"/etc/private-ai-gateway/upstreams.seed.json\\\",\\n        \\\"upstream_pull\\\": {\\n          \\\"url\\\": \\\"https://service.redpill.ai/api/admin/gateway-upstreams/config\\\",\\n          \\\"token\\\": \\\"${PRIVATE_AI_GATEWAY_PULL_TOKEN:?set PRIVATE_AI_GATEWAY_PULL_TOKEN}\\\",\\n          \\\"refresh_seconds\\\": 300,\\n          \\\"request_timeout_seconds\\\": 90\\n        },\\n        \\\"admin_token\\\": \\\"${PRIVATE_AI_GATEWAY_ADMIN_TOKEN:?set PRIVATE_AI_GATEWAY_ADMIN_TOKEN}\\\",\\n        \\\"tls\\\": {\\n          \\\"domain_certificates\\\": [\\n            { \\\"domain\\\": \\\"tee.redpill.ai\\\", \\\"certificate_path\\\": \\\"/evidences/cert-tee.redpill.ai.pem\\\" },\\n            { \\\"domain\\\": \\\"inference.phala.com\\\", \\\"certificate_path\\\": \\\"/evidences/cert-inference.phala.com.pem\\\" },\\n            { \\\"domain\\\": \\\"api.redpill.ai\\\", \\\"certificate_path\\\": \\\"/evidences/cert-api.redpill.ai.pem\\\" }\\n          ]\\n        },\\n        \\\"middleware\\\": {\\n          \\\"control_url\\\": \\\"${PRIVATE_AI_GATEWAY_CONTROL_URL:?set PRIVATE_AI_GATEWAY_CONTROL_URL}\\\",\\n          \\\"control_token\\\": \\\"${PRIVATE_AI_GATEWAY_CONTROL_TOKEN:?set PRIVATE_AI_GATEWAY_CONTROL_TOKEN}\\\",\\n          \\\"tee_only_domains\\\": [\\\"tee.redpill.ai\\\", \\\"inference.phala.com\\\"]\\n        }\\n      }\\n  # Initial upstream routes: seeded into <state_dir>/upstreams.json only when empty,\\n  # then managed at runtime via PUT /v1/admin/upstreams (does not touch this file).\\n  gateway-upstreams:\\n    content: |\\n      []\\n  # node-exporter basic-auth credentials. exporter-toolkit's basic_auth_users maps\\n  # username -> bcrypt hash; both are ${VAR} so dstack substitutes the injected\\n  # secret values when rendering this file into the container — only the literals\\n  # are measured. NODE_EXPORTER_PASSWORD_HASH must be a bcrypt hash\\n  # (`htpasswd -nBC 10 \\\"\\\" | tr -d ':\\\\n'`), NOT the plaintext password; the plaintext\\n  # goes to the external Prometheus scrape config.\\n  node-exporter-web-config:\\n    content: |\\n      basic_auth_users:\\n        ${NODE_EXPORTER_USER:?set NODE_EXPORTER_USER}: ${NODE_EXPORTER_PASSWORD_HASH:?set NODE_EXPORTER_PASSWORD_HASH}\\n\",\"features\":[\"kms\",\"tproxy-net\"],\"gateway_enabled\":true,\"kms_enabled\":true,\"local_key_provider_enabled\":false,\"manifest_version\":2,\"name\":\"\",\"no_instance_id\":false,\"pre_launch_script\":\"#!/bin/bash\\necho \\\"----------------------------------------------\\\"\\necho \\\"Running Phala Cloud Pre-Launch Script v0.0.15\\\"\\necho \\\"----------------------------------------------\\\"\\nset -e\\n\\n# Function: notify host\\n\\nnotify_host() {\\n    if command -v dstack-util >/dev/null 2>&1; then\\n        dstack-util notify-host -e \\\"$1\\\" -d \\\"$2\\\"\\n    else\\n        tdxctl notify-host -e \\\"$1\\\" -d \\\"$2\\\"\\n    fi\\n}\\n\\nnotify_host_hoot_info() {\\n    notify_host \\\"boot.progress\\\" \\\"$1\\\"\\n}\\n\\nnotify_host_hoot_error() {\\n    notify_host \\\"boot.error\\\" \\\"$1\\\"\\n}\\n\\n# Function: Perform Docker cleanup\\nperform_cleanup() {\\n    echo \\\"Pruning unused images\\\"\\n    docker image prune -af\\n    echo \\\"Pruning unused volumes\\\"\\n    docker volume prune -f\\n    notify_host_hoot_info \\\"docker cleanup completed\\\"\\n}\\n\\n# Function: Check Docker login status without exposing credentials\\ncheck_docker_login() {\\n    local registry=\\\"$1\\\"\\n\\n    # When registry is specified, check auth entry for that registry in Docker config\\n    if [[ -n \\\"$registry\\\" ]]; then\\n        local docker_config_path=\\\"${DOCKER_CONFIG:-$HOME/.docker}/config.json\\\"\\n        if [[ -f \\\"$docker_config_path\\\" ]] && grep -q \\\"$registry\\\" \\\"$docker_config_path\\\"; then\\n            return 0\\n        else\\n            return 1\\n        fi\\n    fi\\n\\n    # Fallback check when no explicit registry is provided\\n    if docker info 2>/dev/null | grep -q \\\"Username\\\"; then\\n        return 0\\n    else\\n        return 1\\n    fi\\n}\\n\\n# Main logic starts here\\necho \\\"Starting login process...\\\"\\n\\n# Check if Docker credentials exist\\nif [[ -n \\\"$DSTACK_DOCKER_USERNAME\\\" && -n \\\"$DSTACK_DOCKER_PASSWORD\\\" ]]; then\\n    echo \\\"Docker credentials found\\\"\\n    DOCKER_REGISTRY_TARGET=\\\"${DSTACK_DOCKER_REGISTRY:-docker.io}\\\"\\n    echo \\\"Target Docker registry: $DOCKER_REGISTRY_TARGET\\\"\\n\\n    # Check if already logged in\\n    if check_docker_login \\\"$DSTACK_DOCKER_REGISTRY\\\"; then\\n        echo \\\"Already logged in to Docker registry: $DOCKER_REGISTRY_TARGET\\\"\\n    else\\n        echo \\\"Logging in to Docker registry: $DOCKER_REGISTRY_TARGET\\\"\\n        # Login without exposing password in process list\\n        if [[ -n \\\"$DSTACK_DOCKER_REGISTRY\\\" ]]; then\\n            echo \\\"$DSTACK_DOCKER_PASSWORD\\\" | docker login -u \\\"$DSTACK_DOCKER_USERNAME\\\" --password-stdin \\\"$DSTACK_DOCKER_REGISTRY\\\"\\n        else\\n            echo \\\"$DSTACK_DOCKER_PASSWORD\\\" | docker login -u \\\"$DSTACK_DOCKER_USERNAME\\\" --password-stdin\\n        fi\\n\\n        if [ $? -eq 0 ]; then\\n            echo \\\"Docker login successful: $DOCKER_REGISTRY_TARGET\\\"\\n        else\\n            echo \\\"Docker login failed: $DOCKER_REGISTRY_TARGET\\\"\\n            notify_host_hoot_error \\\"docker login failed\\\"\\n            exit 1\\n        fi\\n    fi\\n# Check if AWS ECR credentials exist\\nelif [[ -n \\\"$DSTACK_AWS_ACCESS_KEY_ID\\\" && -n \\\"$DSTACK_AWS_SECRET_ACCESS_KEY\\\" && -n \\\"$DSTACK_AWS_REGION\\\" && -n \\\"$DSTACK_AWS_ECR_REGISTRY\\\" ]]; then\\n    echo \\\"AWS ECR credentials found\\\"\\n\\n    # Check if AWS CLI is installed\\n    if [ ! -f \\\"./aws/dist/aws\\\" ]; then\\n        notify_host_hoot_info \\\"awscli not installed, installing...\\\"\\n        echo \\\"AWS CLI not installed, installing...\\\"\\n        curl \\\"https://awscli.amazonaws.com/awscli-exe-linux-x86_64-2.24.14.zip\\\" -o \\\"awscliv2.zip\\\"\\n        echo \\\"6ff031a26df7daebbfa3ccddc9af1450 awscliv2.zip\\\" | md5sum -c\\n        if [ $? -ne 0 ]; then\\n            echo \\\"MD5 checksum failed\\\"\\n            notify_host_hoot_error \\\"awscli install failed\\\"\\n            exit 1\\n        fi\\n        unzip awscliv2.zip &> /dev/null\\n    else\\n        echo \\\"AWS CLI is already installed: ./aws/dist/aws\\\"\\n    fi\\n\\n    # Set AWS credentials as environment variables\\n    export AWS_ACCESS_KEY_ID=\\\"$DSTACK_AWS_ACCESS_KEY_ID\\\"\\n    export AWS_SECRET_ACCESS_KEY=\\\"$DSTACK_AWS_SECRET_ACCESS_KEY\\\"\\n    export AWS_DEFAULT_REGION=\\\"$DSTACK_AWS_REGION\\\"\\n\\n    # Set session token if provided (for temporary credentials)\\n    if [[ -n \\\"$DSTACK_AWS_SESSION_TOKEN\\\" ]]; then\\n        echo \\\"AWS session token found, using temporary credentials\\\"\\n        export AWS_SESSION_TOKEN=\\\"$DSTACK_AWS_SESSION_TOKEN\\\"\\n    fi\\n\\n    # Test AWS credentials before attempting ECR login\\n    echo \\\"Testing AWS credentials...\\\"\\n    if ! ./aws/dist/aws sts get-caller-identity &> /dev/null; then\\n        echo \\\"AWS credentials test failed\\\"\\n        # For session token credentials, this might be expected if they're expired\\n        # Log warning but don't fail startup\\n        if [[ -n \\\"$DSTACK_AWS_SESSION_TOKEN\\\" ]]; then\\n            echo \\\"Warning: AWS temporary credentials may have expired, continuing startup\\\"\\n            notify_host_hoot_info \\\"AWS temporary credentials may have expired\\\"\\n        else\\n            echo \\\"AWS credentials test failed\\\"\\n            notify_host_hoot_error \\\"Invalid AWS credentials\\\"\\n            exit 1\\n        fi\\n    else\\n        echo \\\"Logging in to AWS ECR...\\\"\\n        ./aws/dist/aws ecr get-login-password --region $DSTACK_AWS_REGION | docker login --username AWS --password-stdin \\\"$DSTACK_AWS_ECR_REGISTRY\\\"\\n        if [ $? -eq 0 ]; then\\n            echo \\\"AWS ECR login successful\\\"\\n            notify_host_hoot_info \\\"AWS ECR login successful\\\"\\n        else\\n            echo \\\"AWS ECR login failed\\\"\\n            # For session token credentials, don't fail startup if login fails\\n            if [[ -n \\\"$DSTACK_AWS_SESSION_TOKEN\\\" ]]; then\\n                echo \\\"Warning: AWS ECR login failed with temporary credentials, continuing startup\\\"\\n                notify_host_hoot_info \\\"AWS ECR login failed with temporary credentials\\\"\\n            else\\n                notify_host_hoot_error \\\"AWS ECR login failed\\\"\\n                exit 1\\n            fi\\n        fi\\n    fi\\nfi\\n\\nperform_cleanup\\n\\n#\\n# GHCR image pull access verification (pure HTTP, no docker daemon)\\n#\\nif [[ \\\"$DOCKER_REGISTRY_TARGET\\\" == \\\"ghcr.io\\\" && -n \\\"$DSTACK_DOCKER_USERNAME\\\" && -n \\\"$DSTACK_DOCKER_PASSWORD\\\" ]]; then\\n    COMPOSE_IMAGES=$(grep 'image:' /dstack/docker-compose.yaml 2>/dev/null | awk '{print $2}' | tr -d '\\\"'\\\"'\\\" || true)\\n    for img in $COMPOSE_IMAGES; do\\n        [[ \\\"$img\\\" != ghcr.io/* ]] && continue\\n        repo=\\\"${img#ghcr.io/}\\\"; repo=\\\"${repo%%:*}\\\"\\n        tag=\\\"${img##*:}\\\"; [[ \\\"$tag\\\" == \\\"$img\\\" || \\\"$tag\\\" == \\\"$repo\\\" ]] && tag=\\\"latest\\\"\\n        echo \\\"Verifying GHCR pull access: $img\\\"\\n        token=$(curl -sf -u \\\"$DSTACK_DOCKER_USERNAME:$DSTACK_DOCKER_PASSWORD\\\"             \\\"https://ghcr.io/token?service=ghcr.io&scope=repository:${repo}:pull\\\" | jq -r '.token // empty' || true)\\n        if [[ -z \\\"$token\\\" ]]; then\\n            echo \\\"ERROR: GHCR token exchange failed for $img\\\"\\n            notify_host_hoot_error \\\"GHCR token exchange failed: $img\\\"\\n            exit 1\\n        fi\\n        http_code=$(curl -s -o /dev/null -w \\\"%{http_code}\\\" -H \\\"Authorization: Bearer $token\\\"             -H \\\"Accept: application/vnd.oci.image.index.v1+json,application/vnd.oci.image.manifest.v1+json,application/vnd.docker.distribution.manifest.list.v2+json,application/vnd.docker.distribution.manifest.v2+json\\\"             \\\"https://ghcr.io/v2/${repo}/manifests/${tag}\\\")\\n        if [[ \\\"$http_code\\\" != \\\"200\\\" ]]; then\\n            echo \\\"ERROR: GHCR pull access denied for $img (HTTP $http_code)\\\"\\n            notify_host_hoot_error \\\"GHCR pull access denied: $img (HTTP $http_code)\\\"\\n            exit 1\\n        fi\\n        echo \\\"GHCR pull access OK: $img\\\"\\n    done\\nfi\\n\\n#\\n# Pull latest images from docker-compose.yaml so existing CVMs pick up new tags.\\n# Pull is fail-soft: short-lived tokens may expire between login and pull, but\\n# falling back to already-cached images is preferable to blocking boot.\\n#\\necho \\\"Images before pull:\\\"\\ndocker images --format '{{.Repository}}:{{.Tag}} {{.ID}} ({{.CreatedSince}})'\\n\\necho \\\"Pulling latest images from /dstack/docker-compose.yaml...\\\"\\nif docker compose -f /dstack/docker-compose.yaml pull; then\\n    echo \\\"docker compose pull completed\\\"\\n    notify_host_hoot_info \\\"docker compose pull completed\\\"\\nelse\\n    echo \\\"WARNING: docker compose pull failed; continuing with existing images\\\"\\n    notify_host_hoot_info \\\"docker compose pull failed; using existing images\\\"\\nfi\\n\\necho \\\"Images after pull:\\\"\\ndocker images --format '{{.Repository}}:{{.Tag}} {{.ID}} ({{.CreatedSince}})'\\n\\n#\\n# Set root password.\\n#\\necho \\\"Setting root password..\\\"\\n\\n# Check if password files are writable\\nPASSWD_WRITABLE=true\\nif [ ! -w /etc/passwd ]; then\\n    echo \\\"Warning: /etc/passwd is read-only\\\"\\n    PASSWD_WRITABLE=false\\nfi\\nif [ ! -w /etc/shadow ]; then\\n    echo \\\"Warning: /etc/shadow is read-only\\\"\\n    PASSWD_WRITABLE=false\\nfi\\n\\nif [ \\\"$PASSWD_WRITABLE\\\" = \\\"false\\\" ]; then\\n    echo \\\"Skipping password setup due to read-only file system\\\"\\nelse\\n    # Check if chpasswd is available\\n    if command -v chpasswd >/dev/null 2>&1; then\\n        echo \\\"Using chpasswd method\\\"\\n\\n        if [ -n \\\"$DSTACK_ROOT_PASSWORD\\\" ]; then\\n            echo \\\"Setting root password from user..\\\"\\n            echo \\\"root:$DSTACK_ROOT_PASSWORD\\\" | chpasswd\\n            unset DSTACK_ROOT_PASSWORD\\n            echo \\\"Root password set/updated from DSTACK_ROOT_PASSWORD\\\"\\n        elif [ -z \\\"$(grep '^root:' /etc/shadow 2>/dev/null | cut -d: -f2)\\\" ]; then\\n            echo \\\"Setting random root password..\\\"\\n            DSTACK_ROOT_PASSWORD=$(\\n                LC_ALL=C tr -dc 'A-Za-z0-9' < /dev/urandom | dd bs=1 count=32 2>/dev/null\\n            )\\n            echo \\\"root:$DSTACK_ROOT_PASSWORD\\\" | chpasswd\\n            unset DSTACK_ROOT_PASSWORD\\n            echo \\\"Root password set (random auto-init)\\\"\\n        else\\n            echo \\\"Root password already set; no changes.\\\"\\n        fi\\n    else\\n        echo \\\"Using passwd method\\\"\\n\\n        if [ -n \\\"$DSTACK_ROOT_PASSWORD\\\" ]; then\\n            echo \\\"Setting root password from user..\\\"\\n            echo \\\"$DSTACK_ROOT_PASSWORD\\\" | passwd --stdin root 2>/dev/null                 || printf '%s\\n%s\\n' \\\"$DSTACK_ROOT_PASSWORD\\\" \\\"$DSTACK_ROOT_PASSWORD\\\" | passwd root\\n            unset DSTACK_ROOT_PASSWORD\\n            echo \\\"Root password set/updated from DSTACK_ROOT_PASSWORD\\\"\\n        elif [ -z \\\"$(grep '^root:' /etc/shadow 2>/dev/null | cut -d: -f2)\\\" ]; then\\n            echo \\\"Setting random root password..\\\"\\n            DSTACK_ROOT_PASSWORD=$(\\n                LC_ALL=C tr -dc 'A-Za-z0-9' < /dev/urandom | dd bs=1 count=32 2>/dev/null\\n            )\\n            echo \\\"$DSTACK_ROOT_PASSWORD\\\" | passwd --stdin root 2>/dev/null                 || printf '%s\\n%s\\n' \\\"$DSTACK_ROOT_PASSWORD\\\" \\\"$DSTACK_ROOT_PASSWORD\\\" | passwd root\\n            unset DSTACK_ROOT_PASSWORD\\n            echo \\\"Root password set (random auto-init)\\\"\\n        else\\n            echo \\\"Root password already set; no changes.\\\"\\n        fi\\n    fi\\nfi\\n\\n#\\n# Set SSH authorized keys\\n#\\nif mkdir -p /home/root/.ssh 2>/dev/null; then\\n    if [[ -n \\\"$DSTACK_ROOT_PUBLIC_KEY\\\" ]]; then\\n        echo \\\"$DSTACK_ROOT_PUBLIC_KEY\\\" > /home/root/.ssh/authorized_keys\\n        unset $DSTACK_ROOT_PUBLIC_KEY\\n        echo \\\"Root public key set\\\"\\n    fi\\n    if [[ -n \\\"$DSTACK_AUTHORIZED_KEYS\\\" ]]; then\\n        echo \\\"$DSTACK_AUTHORIZED_KEYS\\\" > /home/root/.ssh/authorized_keys\\n        unset $DSTACK_AUTHORIZED_KEYS\\n        echo \\\"Root authorized_keys set\\\"\\n    fi\\n\\n    if [[ -f /dstack/user_config ]] && jq empty /dstack/user_config 2>/dev/null; then\\n        if [[ $(jq 'has(\\\"ssh_authorized_keys\\\")' /dstack/user_config 2>/dev/null) == \\\"true\\\" ]]; then\\n            jq -j '.ssh_authorized_keys' /dstack/user_config >> /home/root/.ssh/authorized_keys\\n            # Remove duplicates if there are multiple keys\\n            if [[ $(cat /home/root/.ssh/authorized_keys | wc -l) -gt 1 ]]; then\\n                sort -u /home/root/.ssh/authorized_keys > /home/root/.ssh/authorized_keys.tmp\\n                mv /home/root/.ssh/authorized_keys.tmp /home/root/.ssh/authorized_keys\\n            fi\\n            echo \\\"Set root authorized_keys from user preferences, total\\\" $(cat /home/root/.ssh/authorized_keys | wc -l) \\\"keys\\\"\\n        fi\\n    fi\\nelse\\n    echo \\\"Warning: Cannot create /home/root/.ssh directory (read-only file system?)\\\"\\n    echo \\\"Skipping SSH key setup\\\"\\nfi\\n\\nif [[ -S /var/run/dstack.sock ]]; then\\n    export DSTACK_APP_ID=$(curl -s --unix-socket /var/run/dstack.sock http://dstack/Info | jq -j .app_id)\\nelif [[ -S /var/run/tappd.sock ]]; then\\n    export DSTACK_APP_ID=$(curl -s --unix-socket /var/run/tappd.sock http://dstack/prpc/Tappd.Info | jq -j .app_id)\\nfi\\n# Check if DSTACK_GATEWAY_DOMAIN is not set, try to get it from user_config or app-compose.json\\n# Priority: user_config > app-compose.json\\nif [[ -z \\\"$DSTACK_GATEWAY_DOMAIN\\\" ]]; then\\n    # First try to get from /dstack/user_config if it exists and is valid JSON\\n    if [[ -f /dstack/user_config ]] && jq empty /dstack/user_config 2>/dev/null; then\\n        if [[ $(jq 'has(\\\"default_gateway_domain\\\")' /dstack/user_config 2>/dev/null) == \\\"true\\\" ]]; then\\n            export DSTACK_GATE